import numpy as np
import keras
from keras import ops

@keras.saving.register_keras_serializable(package="demo")
class ScaledDense(keras.layers.Layer):
    def __init__(self, units, scale=1.0, **kwargs):
        super().__init__(**kwargs)
        self.units, self.scale = units, scale
    def build(self, input_shape):
        self.w = self.add_weight(shape=(input_shape[-1], self.units),
                                 initializer="glorot_uniform", name="w")
        self.b = self.add_weight(shape=(self.units,), initializer="zeros", name="b")
    def call(self, x):
        return self.scale * (ops.matmul(x, self.w) + self.b)
    def get_config(self):
        return {**super().get_config(), "units": self.units, "scale": self.scale}

layer = ScaledDense(4, scale=0.5)
print(tuple(layer(np.ones((2, 3), dtype="float32")).shape))   # (2, 4)
print([tuple(w.shape) for w in layer.weights])                # [(3, 4), (4,)]
clone = ScaledDense.from_config(layer.get_config())
print(clone.units, clone.scale)                               # 4 0.5
